"use strict";
// Texture specs in the build service (Cyrus R1 asset slice). The model writes small declarative TEXTURE SPEC files
// (assets/textures/<name>.json, the Nxeon texture DSL); this module validates them, renders them and runs the
// quality bar, so a bad spec goes back to the model as repair feedback just like a compile error. The portal renders
// the real pack from the returned specs with its own TypeScript copy (lib/cyrus/textures); the two MUST agree:
//   checkSpec  == lib/cyrus/textures/dsl.ts checkSpec
//   render     == lib/cyrus/textures/render.ts render (byte for byte)
//   quality    == lib/cyrus/textures/quality.ts textureQuality
// test/cyrus-assets.test.ts runs both on the shared fixtures in test/fixtures/cyrus-textures. Change both or neither.
// Plain Node, no dependencies, no I/O except the workspace helpers at the bottom.

const fs = require("fs");
const path = require("path");

const TEXTURE_SIZES = [16, 32, 64];
const MAX_OPS = 400;
const MAX_PALETTE = 24;
const MAX_TEXTURES = 24;
const MAX_SPEC_BYTES = 64 * 1024;
const HEX = /^#[0-9a-fA-F]{6}$/;
const KEY = /^[a-z][a-z0-9_]{0,23}$/;
const NAME = /^[a-z][a-z0-9_]{1,31}$/;
const NAMESPACE_RE = /^nx_[a-z0-9]{8}$/;
const TEXTURE_DIR = "assets/textures";
const TEXTURE_FILE_RE = /^assets\/textures\/[a-z][a-z0-9_]{1,31}\.json$/;
// Cyrus r35 legacy (1.21.1): the model binds each texture to a vanilla carrier + custom_model_data number here
// (validator = lib/cyrus/itemmodel/legacy.ts checkLegacyManifest, bundled in itemmodel-spec.js). Part of the texture asset.
const LEGACY_MANIFEST_REL = "assets/legacy-models.json";
const LEGACY_MANIFEST_RE = /^assets\/legacy-models\.json$/;
let IMB = null; // lazy: the bundled itemmodel validator (zod + registry), only needed on legacy builds
const imb = () => (IMB = IMB || require("./itemmodel-spec.js"));

const num = (v, lo, hi) => typeof v === "number" && Number.isFinite(v) && v >= lo && v <= hi;

/** Port of lib/cyrus/textures/dsl.ts checkSpec: same checks, same order, same messages. */
function checkSpec(raw) {
  if (!raw || typeof raw !== "object") return { ok: false, error: "texture must be an object" };
  const r = raw;
  if (typeof r.name !== "string" || !NAME.test(r.name)) return { ok: false, error: "name must be lowercase letters, digits and underscores (2-32 chars)" };
  if (!TEXTURE_SIZES.includes(r.size)) return { ok: false, error: "size must be 16, 32 or 64" };
  const size = r.size;
  if (!r.palette || typeof r.palette !== "object") return { ok: false, error: "palette is required" };
  const palette = {};
  const entries = Object.entries(r.palette);
  if (entries.length === 0 || entries.length > MAX_PALETTE) return { ok: false, error: `palette needs 1-${MAX_PALETTE} colours` };
  for (const [k, v] of entries) {
    if (!KEY.test(k)) return { ok: false, error: `bad palette key ${k}` };
    if (typeof v !== "string" || !HEX.test(v)) return { ok: false, error: `palette ${k} must be #rrggbb` };
    palette[k] = v.toLowerCase();
  }
  if (!Array.isArray(r.ops) || r.ops.length === 0 || r.ops.length > MAX_OPS) return { ok: false, error: `ops needs 1-${MAX_OPS} entries` };
  const col = (c) => typeof c === "string" && c in palette;
  const pos = (v) => num(v, -size, size * 2);
  const ops = [];
  for (const [i, o] of r.ops.entries()) {
    const at = `ops[${i}]`;
    if (!o || typeof o !== "object") return { ok: false, error: `${at} must be an object` };
    const p = o;
    switch (p.op) {
      case "fill": if (!col(p.c)) return { ok: false, error: `${at}: unknown colour` }; ops.push({ op: "fill", c: p.c }); break;
      case "px": if (!pos(p.x) || !pos(p.y) || !col(p.c)) return { ok: false, error: `${at}: bad px` }; ops.push({ op: "px", x: p.x, y: p.y, c: p.c }); break;
      case "rect": if (![p.x, p.y].every(pos) || !num(p.w, 0, size * 2) || !num(p.h, 0, size * 2) || !col(p.c)) return { ok: false, error: `${at}: bad rect` }; ops.push({ op: "rect", x: p.x, y: p.y, w: p.w, h: p.h, c: p.c }); break;
      case "line": if (![p.x1, p.y1, p.x2, p.y2].every(pos) || !col(p.c)) return { ok: false, error: `${at}: bad line` }; ops.push({ op: "line", x1: p.x1, y1: p.y1, x2: p.x2, y2: p.y2, c: p.c }); break;
      case "circle": if (!pos(p.x) || !pos(p.y) || !num(p.r, 0, size) || !col(p.c)) return { ok: false, error: `${at}: bad circle` }; ops.push({ op: "circle", x: p.x, y: p.y, r: p.r, c: p.c, ring: p.ring === true }); break;
      case "poly": {
