// rc11 first-try fixes, each from a repair class recorded in eval fourth1 (image 0.16). Fixtures in test/fixtures/cyrus-rc11 are the
// recorded final specs of the repaired builds (the pre-repair file is not kept by the service; the failing shape is rebuilt from
// the recorded repair message, e.g. the full-tile rect the quality check names).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

/* eslint-disable @typescript-eslint/no-require-imports, @typescript-eslint/no-explicit-any */
const AF = require("../services/modbuilder/autofix.js") as any;
const TX = require("../services/modbuilder/textures.js") as any;
const SND = require("../services/modbuilder/sounds.js") as any;
const SS = require("../services/modbuilder/sound-spec.js") as any;
const YAML = require("../services/modbuilder/node_modules/yaml") as any;
const ROOT = path.join(import.meta.dirname, "..");
const fx = (n: string) => JSON.parse(fs.readFileSync(path.join(ROOT, "test/fixtures/cyrus-rc11", n), "utf8"));

function ws(files: Record<string, string>) {
  const d = fs.mkdtempSync(path.join(os.tmpdir(), "mb-rc11-"));
  for (const [rel, text] of Object.entries(files)) { fs.mkdirSync(path.dirname(path.join(d, rel)), { recursive: true }); fs.writeFileSync(path.join(d, rel), text); }
  return d;
}

describe("rc11: List<Sub> -> List<Super> from Stream.toList() (tex-dragon-sword-32)", () => {
  const rel = "src/main/java/dev/nxeon/plugins/dragonsword/DragonSwordPlugin.java";
  const src = [
    "package dev.nxeon.plugins.dragonsword;",
    "class X {",
    "    void f(java.util.List<String> lines) {",
    "        java.util.List<net.kyori.adventure.text.Component> lore = lines.stream()",
    "                .map(s -> net.kyori.adventure.text.Component.text(s))",
    "                .toList();",
    "    }",
    "}",
    "",
  ].join("\n");
  const out = `${rel}:6: error: incompatible types: List<TextComponent> cannot be converted to List<Component>\n                .toList();\n                       ^\n1 error\n`;
  it("collects with the declared element type", () => {
    const d = ws({ [rel]: src });
    const r = AF.fixListSubtype(out, d);
    assert.equal(r.fixes.length, 1);
    assert.match(fs.readFileSync(path.join(d, rel), "utf8"), /\.collect\(java\.util\.stream\.Collectors\.<Component>toList\(\)\)/);
    assert.equal(r.fixes[0].kind, "list-subtype");
  });
  it("is part of fixCompile and leaves a line with two toList() calls to the model", () => {
    const d = ws({ [rel]: src.replace(".toList();", ".toList().stream().toList();") });
    assert.equal(AF.fixListSubtype(out, d).fixes.length, 0);
    const d2 = ws({ [rel]: src });
    assert.ok(AF.fixCompile(out, d2, "1.21.11", {}).fixes.some((f: any) => f.kind === "list-subtype"));
  });
  it("only touches src/main/java", () => {
    const d = ws({ "x/Y.java": src });
    assert.equal(AF.fixListSubtype(out.replace(rel, "x/Y.java"), d).fixes.length, 0);
  });
});

describe("rc11: plugin.yml with an unquoted ': ' in a value (snd-wand-spells)", () => {
  const bad = [
    "name: WandSpells",
    "version: 1.0.0",
    "main: dev.nxeon.plugins.wandspells.WandSpells",
    "api-version: '1.21'",
    "description: A magic wand with three switchable spells: fireball, frost, and heal",
    "commands:",
    "  wand:",
    "    description: Give yourself the wand: op only",
    "    usage: /wand",
    "",
  ].join("\n");
  it("the recorded failure does not parse", () => { assert.throws(() => YAML.parse(bad)); });
  it("quotes the values and keeps the document identical otherwise", () => {
    const fixed = AF.fixYamlScalars(bad, (t: string) => YAML.parse(t));
    const y = YAML.parse(fixed);
    assert.equal(y.description, "A magic wand with three switchable spells: fireball, frost, and heal");
    assert.equal(y.commands.wand.description, "Give yourself the wand: op only");
    assert.equal(y.commands.wand.usage, "/wand");
    assert.equal(y["api-version"], "1.21");
  });
  it("leaves valid files, block scalars and quoted values alone", () => {
    assert.equal(AF.fixYamlScalars("name: A\ndescription: fine text\n", (t: string) => YAML.parse(t)), null);
    const block = "name: A\ndescription: |\n  line one: x\n  line two\nversion: 1\n";
    assert.equal(AF.fixYamlScalars(block, (t: string) => YAML.parse(t)), null);
    assert.equal(AF.fixYamlScalars('name: A\ndescription: "a: b"\n', (t: string) => YAML.parse(t)), null);
  });
  it("gives up (null) when quoting does not make the file parse", () => {
    assert.equal(AF.fixYamlScalars("name: A\ndescription: x: y\n  broken: [\n", (t: string) => YAML.parse(t)), null);
  });
});

describe("rc11: every-pixel-solid panel textures are inset mechanically (tex-shop-counter-gui, ast-gui-textured)", () => {
  function solid(name: string) {
    const spec = fx(`${name}-repaired.json`);
    const i = spec.ops.findIndex((o: any) => o.op === "rect" && o.w === 12 && o.h === 12);
    assert.ok(i >= 0);
    spec.ops[i] = { op: "rect", x: 0, y: 0, w: 16, h: 16, c: spec.ops[i].c };
    return spec;
  }
  for (const name of ["shop_panel", "shop_panel_vignette"]) {
    it(`${name}: the full-tile drawing fails the quality bar as recorded`, () => {
      const q = TX.textureQuality(TX.render(TX.checkSpec(solid(name)).spec));
      assert.equal(q.verdict, "fail");
      assert.ok(q.checks.some((c: any) => c.id === "transparency" && c.status === "fail" && c.value === 1));
    });
    it(`${name}: checkWorkspaceTextures rewrites the file and the texture passes without a model repair`, () => {
      const d = ws({ [`assets/textures/${name}.json`]: JSON.stringify(solid(name)) });
      const r = TX.checkWorkspaceTextures(d, { namespace: "nx_abcd1234", javaFiles: [] });
      assert.equal(r.results[0].ok, true, JSON.stringify(r.problems));
      assert.equal(r.problems.length, 0);
      assert.ok(r.normalised.some((x: string) => /every pixel was solid/.test(x)));
      assert.notEqual(r.results[0].quality.verdict, "fail");
      const onDisk = JSON.parse(fs.readFileSync(path.join(d, `assets/textures/${name}.json`), "utf8"));
      assert.equal(onDisk.size, 16);
      assert.deepEqual(onDisk.palette, solid(name).palette, "palette unchanged");
